     1→import { connectGM } from './websocket';
     2→import { initCanvas } from './canvas';
     3→import { initTokenLayer } from './tokens';
     4→import { createViewport } from './viewport';
     5→import type { FogStroke } from './canvas';
     6→import * as api from './api';
     7→
     8→// --- URL params ---
     9→const fragment = new URLSearchParams(location.hash.slice(1));
    10→const adventureId = fragment.get('id') ?? '';
    11→const password = fragment.get('password') ?? '';
    12→
    13→if (!adventureId || !password) {
    14→  document.body.innerHTML = '<p style="padding:2rem">Missing adventure ID or password. <a href="/">Return home</a></p>';
    15→  throw new Error('Missing params');
    16→}
    17→
    18→// --- State ---
    19→let brushRadius = 50;
    20→let brushMode: 'reveal' | 'fog' = 'reveal';
    21→let activeImageId: string | null = null;
    22→let imageList: api.ImageRecord[] = [];
    23→let playerRoster: Array<{ tokenId: string; name: string; color: string; online: boolean }> = [];
    24→
    25→// --- DOM ---
    26→const adventureNameEl = document.getElementById('adventure-name')!;
    27→const inviteLinkEl = document.getElementById('invite-link')!;
    28→const copyInviteBtn = document.getElementById('copy-invite')!;
    29→const brushSizeSlider = document.getElementById('brush-size') as HTMLInputElement;
    30→const brushSizeLabel = document.getElementById('brush-size-label')!;
    31→const modeRevealBtn = document.getElementById('mode-reveal')!;
    32→const modeFogBtn = document.getElementById('mode-fog')!;
    33→const gallery = document.getElementById('gallery')!;
    34→const uploadInput = document.getElementById('upload-input') as HTMLInputElement;
    35→const statusBar = document.getElementById('status-bar')!;
    36→const canvasArea = document.getElementById('canvas-area')!;
    37→
    38→// --- Canvas ---
    39→const canvasCtrl = initCanvas(canvasArea);
    40→
    41→// --- Viewport ---
    42→const viewport = createViewport();
    43→viewport.attach(canvasArea, canvasCtrl.getWrapper(), () => canvasCtrl.getImageSize());
    44→
    45→// --- Token layer (non-interactive for GM) ---
    46→const tokenCtrl = initTokenLayer(
    47→  canvasCtrl.getWrapper(),
    48→  () => canvasCtrl.getImageSize(),
    49→  (x, y) => viewport.screenToImage(x, y),
    50→  { interactive: false }
    51→);
    52→
    53→// --- WebSocket ---
    54→const ws = connectGM(adventureId, password);
    55→
    56→ws.on('connect', () => { statusBar.textContent = ''; });
    57→ws.on('disconnect', () => { statusBar.textContent = 'Reconnecting\u2026'; });
    58→ws.on('error', (msg) => { console.error('WS error', msg); });
    59→
    60→ws.on('joined', async (msg) => {
    61→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    62→  adventureNameEl.textContent = adv.name;
    63→
    64→  try {
    65→    const advData = await api.getAdventure(adventureId, password);
    66→    const inviteUrl = `${location.origin}/player#link=${encodeURIComponent(advData.player_link)}`;
    67→    inviteLinkEl.textContent = inviteUrl;
    68→    copyInviteBtn.onclick = () => {
    69→      navigator.clipboard.writeText(inviteUrl).catch(() => {});
    70→    };
    71→  } catch {}
    72→
    73→  activeImageId = adv.activeImageId;
    74→  imageList = await api.listImages(adventureId, password);
    75→  renderGallery();
    76→
    77→  if (activeImageId) {
    78→    const img = imageList.find(i => i.id === activeImageId);
    79→    if (img) {
    80→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    81→      viewport.resetView();
    82→      if (typeof msg.fogMask === 'string') {
    83→        await canvasCtrl.applyFogMask(msg.fogMask);
    84→      }
    85→    }
    86→  }
    87→
    88→  const tokens = msg.tokens as Array<{ id: string; name: string; color: string; x: number; y: number }>;
    89→  for (const token of tokens) {
    90→    tokenCtrl.addToken(token);
    91→  }
    92→});
    93→
    94→ws.on('fog:stroke', (msg) => {
    95→  if (msg.imageId === activeImageId) {
    96→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
    97→  }
    98→});
    99→
   100→ws.on('fog:stroke:batch', (msg) => {
   101→  if (msg.imageId === activeImageId) {
   102→    for (const stroke of msg.strokes as FogStroke[]) {
   103→      canvasCtrl.applyStroke(stroke);
   104→    }
   105→  }
   106→});
   107→
   108→ws.on('token:added', (msg) => {
   109→  const token = msg.token as { id: string; name: string; color: string; x: number; y: number };
   110→  tokenCtrl.addToken(token);
   111→});
   112→
   113→ws.on('token:moved', (msg) => {
   114→  tokenCtrl.moveToken(msg.tokenId as string, msg.x as number, msg.y as number);
   115→});
   116→
   117→ws.on('token:removed', (msg) => {
   118→  tokenCtrl.removeToken(msg.tokenId as string);
   119→});
   120→
   121→ws.on('player:roster', (msg) => {
   122→  playerRoster = msg.players as typeof playerRoster;
   123→});
   124→
   125→ws.on('map:switched', async (msg) => {
   126→  activeImageId = msg.imageId as string;
   127→  imageList = await api.listImages(adventureId, password);
   128→  const img = imageList.find(i => i.id === activeImageId);
   129→  if (img) {
   130→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
   131→    viewport.resetView();
   132→    if (typeof msg.fogMask === 'string') {
   133→      await canvasCtrl.applyFogMask(msg.fogMask);
   134→    }
   135→  }
   136→  renderGallery();
   137→  tokenCtrl.render();
   138→});
   139→
   140→// --- Gallery ---
   141→function renderGallery() {
   142→  gallery.innerHTML = '';
   143→  for (const img of imageList) {
   144→    const item = document.createElement('div');
   145→    item.className = 'gallery-item' + (img.id === activeImageId ? ' active' : '');
   146→
   147→    const thumb = document.createElement('img');
   148→    thumb.src = `/uploads/${img.filename}`;
   149→    thumb.alt = img.original_name;
   150→    thumb.title = img.original_name;
   151→    item.appendChild(thumb);
   152→
   153→    item.addEventListener('click', () => {
   154→      ws.send({ type: 'map:switch', imageId: img.id });
   155→    });
   156→    gallery.appendChild(item);
   157→  }
   158→}
   159→
   160→// --- Upload ---
   161→uploadInput.addEventListener('change', async () => {
   162→  const file = uploadInput.files?.[0];
   163→  if (!file) return;
   164→  try {
   165→    await api.uploadImage(adventureId, password, file);
   166→    imageList = await api.listImages(adventureId, password);
   167→    renderGallery();
   168→  } catch (e) {
   169→    console.error('Upload failed', e);
   170→  }
   171→  uploadInput.value = '';
   172→});
   173→
   174→// --- Brush controls ---
   175→brushSizeSlider.addEventListener('input', () => {
   176→  brushRadius = parseInt(brushSizeSlider.value, 10);
   177→  brushSizeLabel.textContent = `${brushRadius}px`;
   178→});
   179→
   180→function setMode(mode: 'reveal' | 'fog') {
   181→  brushMode = mode;
   182→  modeRevealBtn.classList.toggle('active', mode === 'reveal');
   183→  modeFogBtn.classList.toggle('active', mode === 'fog');
   184→}
   185→
   186→modeRevealBtn.addEventListener('click', () => setMode('reveal'));
   187→modeFogBtn.addEventListener('click', () => setMode('fog'));
   188→
   189→// --- Brush interaction ---
   190→let isDrawing = false;
   191→const pending: FogStroke[] = [];
   192→let lastFlush = 0;
   193→const FLUSH_INTERVAL = 1000 / 60;
   194→
   195→function makeStroke(clientX: number, clientY: number): FogStroke {
   196→  const pos = viewport.screenToImage(clientX, clientY);
   197→  return { x: pos.x, y: pos.y, radius: brushRadius, mode: brushMode };
   198→}
   199→
   200→function flushPending() {
   201→  if (pending.length === 0) return;
   202→  if (pending.length === 1) {
   203→    ws.send({ type: 'fog:stroke', stroke: pending[0] });
   204→  } else {
   205→    ws.send({ type: 'fog:stroke:batch', strokes: pending.slice() });
   206→  }
   207→  pending.length = 0;
   208→  lastFlush = Date.now();
   209→}
   210→
   211→viewport.onInteractStart((ev: PointerEvent) => {
   212→  if (!activeImageId) return;
   213→  isDrawing = true;
   214→  const stroke = makeStroke(ev.clientX, ev.clientY);
   215→  canvasCtrl.applyStroke(stroke);
   216→  pending.push(stroke);
   217→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   218→});
   219→
   220→viewport.onPointerMove((ev: PointerEvent) => {
   221→  const pos = viewport.screenToImage(ev.clientX, ev.clientY);
   222→  canvasCtrl.drawBrushPreview(pos.x, pos.y, brushRadius);
   223→  if (!isDrawing) return;
   224→  const stroke = makeStroke(ev.clientX, ev.clientY);
   225→  canvasCtrl.applyStroke(stroke);
   226→  pending.push(stroke);
   227→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   228→});
   229→
   230→viewport.onInteractEnd(() => {
   231→  if (!isDrawing) return;
   232→  isDrawing = false;
   233→  flushPending();
   234→});
   235→
   236→viewport.onPointerLeave(() => {
   237→  canvasCtrl.clearBrushPreview();
   238→  if (isDrawing) {
   239→    isDrawing = false;
   240→    flushPending();
   241→  }
   242→});
   243→

