     8→// --- URL params ---
     9→const fragment = new URLSearchParams(location.hash.slice(1));
    10→const adventureId = fragment.get('adventureId') ?? '';
    11→const playerLink = fragment.get('link') ?? '';
    12→const playerName = fragment.get('name') ?? 'Player';
    13→const playerColor = fragment.get('color') ?? '#e74c3c';
    14→
    15→if (!adventureId || !playerLink) {
    16→  const p = document.createElement('p');
    17→  p.style.cssText = 'padding:2rem';
    18→  p.textContent = 'Invalid invite link. ';
    19→  const a = document.createElement('a');
    20→  a.href = '/';
    21→  a.textContent = 'Return home';
    22→  p.appendChild(a);
    23→  document.body.textContent = '';
    24→  document.body.appendChild(p);
    25→  throw new Error('Missing params');
    26→}
    27→
    28→// --- DOM ---
    29→const adventureNameEl = document.getElementById('adventure-name')!;
    30→const playerInfoEl = document.getElementById('player-info')!;
    31→const canvasArea = document.getElementById('canvas-area')!;
    32→
    33→// Player color dot + name
    34→const dot = document.createElement('span');
    35→dot.className = 'player-dot';
    36→dot.style.background = playerColor;
    37→playerInfoEl.appendChild(dot);
    38→playerInfoEl.appendChild(document.createTextNode(playerName));
    39→
    40→// Hide canvas until fog is applied to prevent flash
    41→canvasArea.style.visibility = 'hidden';
    42→
    43→// --- State ---
    44→let activeImageId: string | null = null;
    45→let ownTokenId: string | null = null;
    46→let imageList: api.ImageRecord[] = [];
    47→
    48→// --- Canvas (opaque fog) ---
    49→const canvasCtrl = initCanvas(canvasArea, { mode: 'player' });
    50→
    51→// --- Viewport ---
    52→const viewport = createViewport();
    53→viewport.attach(canvasArea, canvasCtrl.getWrapper(), () => canvasCtrl.getImageSize());
    54→
    55→// --- Token layer ---
    56→const tokenCtrl = initTokenLayer(
    57→  canvasCtrl.getWrapper(),
    58→  () => canvasCtrl.getImageSize(),
    59→  (x, y) => viewport.screenToImage(x, y),
    60→  { interactive: true }
    61→);
    62→
    63→// Wire token drag through viewport gesture system
    64→viewport.onInteractStart(ev => tokenCtrl.handlePointerDown(ev));
    65→viewport.onPointerMove(ev => tokenCtrl.handlePointerMove(ev));
    66→viewport.onInteractEnd(() => tokenCtrl.handlePointerUp());
    67→
    68→// --- WebSocket ---
    69→const ws = connectPlayer(adventureId, playerLink, playerName, playerColor);
    70→
    71→ws.on('joined', async (msg) => {
    72→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    73→  adventureNameEl.textContent = adv.name;
    74→  document.title = `${adv.name} — Player`;
    75→  activeImageId = adv.activeImageId;
    76→  ownTokenId = typeof msg.yourTokenId === 'string' ? msg.yourTokenId : null;
    77→
    78→  try {
    79→    imageList = await api.listImagesAsPlayer(adventureId, playerLink);
    80→  } catch {
    81→    imageList = [];
    82→  }
    83→
    84→  if (activeImageId) {
    85→    const img = imageList.find(i => i.id === activeImageId);
    86→    if (img) {
    87→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    88→      viewport.resetView();
    89→      if (typeof msg.fogMask === 'string') {
    90→        await canvasCtrl.applyFogMask(msg.fogMask);
    91→      }
    92→    }
    93→  }
    94→
    95→  // Reveal canvas only after fog is applied
    96→  canvasArea.style.visibility = 'visible';
    97→
    98→  // Render existing tokens
    99→  const tokens = msg.tokens as Array<{ id: string; name: string; color: string; x: number; y: number }>;
   100→  for (const token of tokens) {
   101→    tokenCtrl.addToken(token);
   102→  }
   103→
   104→  // Enable drag on own token
   105→  if (ownTokenId) {
   106→    const tid = ownTokenId;
   107→    tokenCtrl.enableDrag(tid, (x, y) => {
   108→      ws.send({ type: 'token:move', tokenId: tid, x, y });
   109→    });
   110→  }
   111→
   112→  tokenCtrl.render();
   113→});
   114→
   115→ws.on('fog:stroke', (msg) => {
   116→  if (msg.imageId === activeImageId) {
   117→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
   118→  }
   119→});
   120→
   121→ws.on('fog:stroke:batch', (msg) => {
   122→  if (msg.imageId === activeImageId) {
   123→    for (const stroke of msg.strokes as FogStroke[]) {
   124→      canvasCtrl.applyStroke(stroke);
   125→    }
   126→  }
   127→});
   128→
   129→ws.on('fog:reset', (msg) => {
   130→  if (msg.imageId === activeImageId && typeof msg.fogMask === 'string') {
   131→    canvasCtrl.applyFogMask(msg.fogMask as string);
   132→  }
   133→});
   134→
   135→ws.on('token:moved', (msg) => {
   136→  tokenCtrl.moveToken(msg.tokenId as string, msg.x as number, msg.y as number);
   137→});
   138→
   139→ws.on('token:added', (msg) => {
   140→  const token = msg.token as { id: string; name: string; color: string; x: number; y: number };
   141→  tokenCtrl.addToken(token);
   142→});
   143→
   144→ws.on('token:removed', (msg) => {
   145→  tokenCtrl.removeToken(msg.tokenId as string);
   146→});
   147→
   148→ws.on('map:switched', async (msg) => {
   149→  activeImageId = msg.imageId as string;
   150→  try {
   151→    imageList = await api.listImagesAsPlayer(adventureId, playerLink);
   152→  } catch {}
   153→  const img = imageList.find(i => i.id === activeImageId);
   154→  if (img) {
   155→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
   156→    viewport.resetView();
   157→    if (typeof msg.fogMask === 'string') {
   158→      await canvasCtrl.applyFogMask(msg.fogMask);
   159→    }
   160→  }
   161→  tokenCtrl.render();
   162→});
   163→
   164→ws.on('player:joined', (msg) => {
   165→  showToast(`${msg.playerName as string} joined`);
   166→});
   167→
   168→ws.on('player:left', (msg) => {
   169→  showToast(`${msg.playerName as string} left`);
   170→});
   171→
   172→ws.on('player:removed', () => {
   173→  ws.close();
   174→  document.body.textContent = '';
   175→  const p = document.createElement('p');
   176→  p.style.cssText = 'padding:2rem';
   177→  p.textContent = 'You have been removed from this session. ';
   178→  const a = document.createElement('a');
   179→  a.href = '/';
   180→  a.textContent = 'Return home';
   181→  p.appendChild(a);
   182→  document.body.appendChild(p);
   183→});
   184→
   185→function showToast(text: string) {
   186→  const toast = document.createElement('div');
   187→  toast.className = 'toast';
   188→  toast.textContent = text;
   189→  document.body.appendChild(toast);
   190→  setTimeout(() => toast.remove(), 2500);
   191→}
   192→

