*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, sans-serif;
  background: #0d0d1a;
  color: #e0e0e0;
  height: 100vh;
  overflow: hidden;
}

/* ── Home page ── */
body.home {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
}
.home-main { width: 100%; max-width: 480px; padding: 2rem; }
.home-main h1 { font-size: 2rem; margin-bottom: 1.5rem; text-align: center; }
.card {
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1rem;
}
.card h2 { margin-bottom: 1rem; font-size: 1.1rem; }
.card label { display: flex; flex-direction: column; gap: 4px; margin-bottom: 0.75rem; font-size: 0.85rem; color: #aaa; }
.card input[type=text],
.card input[type=password],
.card input[type=color] {
  padding: 0.4rem 0.6rem;
  background: #0d0d1a;
  border: 1px solid #333;
  border-radius: 4px;
  color: #e0e0e0;
  font-size: 1rem;
}
.card input[type=color] { height: 2rem; cursor: pointer; }
.card button {
  width: 100%;
  padding: 0.5rem;
  background: #4a4aff;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}
.card button:hover { background: #3333cc; }
.error { color: #e74c3c; margin-top: 0.5rem; font-size: 0.85rem; }

/* ── GM page layout ── */
body.gm {
  display: grid;
  grid-template-rows: 44px 1fr;
  grid-template-columns: 180px 1fr 180px;
  grid-template-areas:
    "topbar topbar topbar"
    "left   canvas right";
}

#topbar {
  grid-area: topbar;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0 1rem;
  background: #1a1a2e;
  border-bottom: 1px solid #2a2a4a;
  overflow: hidden;
}
#adventure-name { font-weight: 600; white-space: nowrap; }
.invite-row { display: flex; align-items: center; gap: 0.5rem; flex: 1; min-width: 0; }
.invite-link-text { font-size: 0.75rem; color: #888; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; }
.invite-row button { flex-shrink: 0; padding: 0.2rem 0.5rem; background: #2a2a4a; border: 1px solid #444; border-radius: 4px; color: #ccc; cursor: pointer; font-size: 0.8rem; }

#sidebar-left {
  grid-area: left;
  background: #111122;
  border-right: 1px solid #2a2a4a;
  padding: 1rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  overflow-y: auto;
}
.control-group label { font-size: 0.8rem; color: #aaa; display: block; margin-bottom: 0.4rem; }
.control-group input[type=range] { width: 100%; accent-color: #4a4aff; }
.mode-buttons { display: flex; gap: 0.5rem; }
.mode-buttons button {
  flex: 1;
  padding: 0.35rem 0;
  background: #1a1a2e;
  border: 1px solid #333;
  border-radius: 4px;
  color: #aaa;
  cursor: pointer;
  font-size: 0.85rem;
}
.mode-buttons button.active { background: #4a4aff; border-color: #4a4aff; color: #fff; }
#status-bar { font-size: 0.75rem; color: #555; }

#canvas-area {
  grid-area: canvas;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  overflow: hidden;
  position: relative;
  touch-action: none;
}

#sidebar-right {
  grid-area: right;
  background: #111122;
  border-left: 1px solid #2a2a4a;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
#gallery {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.gallery-item {
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  overflow: hidden;
  background: #0d0d1a;
}
.gallery-item:hover { border-color: #4a4aff88; }
.gallery-item.active { border-color: #4a4aff; }
.gallery-item img { width: 100%; height: 80px; object-fit: cover; display: block; }
.upload-row { padding: 0.5rem; border-top: 1px solid #2a2a4a; }
.upload-btn {
  display: block;
  text-align: center;
  padding: 0.4rem;
  background: #1a1a2e;
  border: 1px dashed #444;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.85rem;
  color: #aaa;
}
.upload-btn:hover { border-color: #4a4aff; color: #ccc; }

/* ── Player page ── */
body.player {
  display: grid;
  grid-template-rows: 44px 1fr;
  grid-template-areas:
    "topbar"
    "canvas";
}

body.player #topbar {
  grid-area: topbar;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0 1rem;
  background: #1a1a2e;
  border-bottom: 1px solid #2a2a4a;
  overflow: hidden;
}

body.player #adventure-name { font-weight: 600; white-space: nowrap; }

body.player #canvas-area {
  grid-area: canvas;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  overflow: hidden;
  position: relative;
  touch-action: none;
}

#player-info {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
}

.player-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.3);
  flex-shrink: 0;
}

.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(26,26,46,0.95);
  border: 1px solid #2a2a4a;
  border-radius: 4px;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  color: #ccc;
  pointer-events: none;
  z-index: 100;
}

