  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
}
.player-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.3);
  flex-shrink: 0;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(26, 26, 46, 0.95);
  border: 1px solid #2a2a4a;
  border-radius: 4px;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  color: #ccc;
  pointer-events: none;
  z-index: 100;
}

/* ── Removal overlay ── */
.removal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  background: rgba(13, 13, 26, 0.92);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 200;
}
.removal-overlay p {
  font-size: 1.1rem;
  color: #ccc;
}
.removal-overlay a {
  color: #4a4aff;
  text-decoration: none;
}
.removal-overlay a:hover { text-decoration: underline; }

